    /* ---------- Simulation step ---------- */

    // The hand holding the glass straightens it up as it fills, like a real pour.
    updateGlassTilt(dt){
        let t = this.smoothStep(Math.min(1, this.getGlassFill01() * 1.7));
        let target = this.glass.restAngle + (this.glass.uprightAngle - this.glass.restAngle) * t;
        let ease = 1 - Math.pow(0.2, dt);
        this.glass.angle += (target - this.glass.angle) * ease;
        this.createGlass();
    }

    update(dt){
