    }

    Length2(){
        return this.x * this.x + this.y * this.y;
    }

    GetNormal(){
        return new Vector2(this.y, -this.x);
    }

    Dot(vec){
        return this.x * vec.x + this.y * vec.y
    }

    Log(){
