        ctx.moveTo(a.x + normal.x * r, a.y + normal.y * r);
        ctx.lineTo(b.x + normal.x * r, b.y + normal.y * r);
        ctx.lineTo(b.x - normal.x * r, b.y - normal.y * r);
        ctx.lineTo(a.x - normal.x * r, a.y - normal.y * r);
        ctx.closePath();
        if(fill){
            ctx.fillStyle = fill;
            ctx.fill();
        }
